NAME = 'SloKJV: Slovenian translation of Holy Bible King James Version (1769)'
BOOK = 'Revelation of John'

CHAPTERS = {
    1: {
        1: 'Razodetje Jezusa Kristusa, ki mu ga je dal Bog, da bi pokazal svojim služabnikom stvari, ki se morajo v kratkem zgoditi; in poslal je ter to po svojem angelu predstavil svojemu služabniku Janezu,',
        2: 'ki je pričeval o Božji besedi in o pričevanju Jezusa Kristusa in o vseh stvareh, ki jih je videl.',
        3: 'Blagoslovljen je, kdor bere in tisti, ki slišijo besede te prerokbe in se držijo teh stvari, ki so v njej zapisane; kajti čas je blizu.',
        4: 'Janez sedmim cerkvam, ki so v Aziji: »Milost bodi vam in mir od njega, ki je in ki je bil in ki pride in od sedmih Duhov, ki so pred njegovim prestolom',
        5: 'in od Jezusa Kristusa, ki je zvesta priča in prvorojenec izmed umrlih in princ kraljev zemlje. Njemu, ki nas je vzljubil in nas je v svoji lastni krvi umil naših grehov',
        6: 'in nas naredil kralje in duhovnike Bogu ter svojemu Očetu; njemu bodi slava in gospostvo na veke vekov. Amen.',
        7: 'Glej, prihaja z oblaki in videlo ga bo vsako oko in tudi tisti, ki so ga prebodli in zaradi njega bodo žalovala vsa sorodstva zemlje. Točno tako: ›Amen.‹«',
        8: '§ »Jaz sem Alfa in Omega, začetek in konec,« govori Gospod, ki je in ki je bil in ki pride, Vsemogočni.',
        9: 'Jaz, Janez, ki sem tudi vaš brat in družabnik v stiski in v kraljestvu in potrpežljivosti Jezusa Kristusa, sem bil zaradi Božje besede in zaradi pričevanja o Jezusu Kristusu na otoku, ki se imenuje Patmos.',
        10: 'Na Gospodov dan sem bil v Duhu in za seboj sem zaslišal močan glas kakor od trobente,',
        11: '§ rekoč: »Jaz sem Alfa in Omega, prvi in zadnji.« In: »Kar vidiš, zapiši v knjigo in jo pošlji sedmim cerkvam, ki so v Aziji: v Efez in v Smirno in v Pêrgamon in v Tiatiro in v Sarde in v Filadelfijo in v Laodikejo.«',
        12: 'In obrnil sem se, da vidim glas, ki je govoril z menoj. In ko sem se obrnil, sem zagledal sedem zlatih svečnikov',
        13: 'in sredi sedmih svečnikov nekoga, podobnega Sinu človekovemu, oblečenega z obleko, ki sega do stopal in okoli prsi opasanega z zlatim pasom.',
        14: 'Njegova glava in njegovi lasje so bili beli kakor volna, tako beli kakor sneg in njegove oči so bile kakor plamen ognja',
        15: 'in njegova stopala podobna čistemu bronu, kakor če bi bila žgana v talilni peči in njegov glas kakor šum mnogih vodá.',
        16: 'In v svoji desnici je imel sedem zvezd in iz njegovih ust je izhajal oster, dvorezen meč in njegovo obličje je bilo, kot [kadar] sonce sije v svoji môči.',
        17: 'In ko sem ga zagledal, sem padel k njegovim stopalom kakor mrtev. In svojo desnico je položil name ter mi rekel: »Ne boj se; jaz sem prvi in zadnji.',
        18: '§ Jaz sem ta, ki živi in je bil mrtev; in glej, živ sem na vékomaj, Amen; in ključe imam od pekla in od smrti.',
        19: 'Zapiši stvari, ki si jih videl, in stvari, ki so, in stvari, ki bodo odslej;',
        20: 'skrivnost sedmih zvezd, ki jih vidiš v moji desni in sedmih zlatih svečnikov. Sedem zvezd so angeli sedmih cerkvá in sedem svečnikov, ki jih vidiš, je sedem cerkvá.«',
    },
    2: {
        1: '»Angelu cerkve v Efezu piši: ›Te stvari govori on, ki v svoji desnici drži sedem zvezd, ki hodi v sredi sedmih zlatih svečnikov;',
        2: 'poznam tvoja dela in tvoj trud in tvojo potrpežljivost in kako ne moreš prenašati teh, ki so hudobni in preizkusil si tiste, ki pravijo, da so apostoli, pa to niso in si jih našel lažnivce.',
        3: 'In prenašal si in imaš potrpežljivost in si se trudil zaradi mojega imena in nisi izgubil poguma.',
        4: 'Vendar imam nekaj proti tebi, kajti zapustil si svojo prvo ljubezen.',
        5: '§ Spomni se torej, od kod si padel in se pokesaj in opravljaj prva dela, sicer bom hitro prišel k tebi in bom odstranil tvoj svečnik z njegovega mesta, razen če se ne pokesaš.',
        6: 'Toda to imaš, da sovražiš dejanja nikolajevcev, ki jih tudi sam sovražim.‹',
        7: 'Kdor ima uho, naj sliši, kaj Duh govori cerkvam: ›Tistemu, ki premaga, bom dal jesti od drevesa življenja, ki je na sredini Božjega raja.‹«',
        8: '»In angelu cerkve v Smirni piši: ›Te stvari govori prvi in zadnji, ki je bil mrtev in je živ;',
        9: '§ poznam tvoja dela in stisko in revščino (toda bogat si) in poznam bogokletje teh, ki pravijo, da so Judje, pa niso, temveč so Satanova sinagoga.',
        10: 'Ne boj se nobene od teh stvari, ki jih boš pretrpel. Glej, hudič bo nekatere izmed vas vrgel v ječo, da boste lahko preizkušeni in deset dni boste imeli stisko. Bodi zvest do smrti in dal ti bom krono življenja.‹',
        11: 'Kdor ima uho, naj sliši, kaj Duh govori cerkvam: ›Kdor premaga, ne bo poškodovan od druge smrti.‹«',
        12: '»In angelu cerkve v Pêrgamonu piši: ›Te besede govori on, ki ima oster meč z dvema ostrinama;',
        13: 'poznam tvoja dela in kje prebivaš, celó kjer je Satanov prestol. In trdno držiš moje ime in moje vere nisi zanikal celó v tistih dneh, v katerih je bil Antípa, moj zvesti mučenec, ki je bil umorjen med vami, kjer prebiva Satan.',
        14: 'Toda zoper tebe imam nekaj stvari, ker imaš tam tiste, ki se drže Bileámovega nauka, ki je učil Baláka metati kamen spotike pred Izraelove otroke, da jedo stvari žrtvovane malikom in da zagrešijo prešuštvo.',
        15: '§ Tako imaš tudi tiste, ki se držijo nauka nikolajevcev, katerih besedo sovražim.',
        16: '§ Pokesaj se, sicer bom hitro prišel k tebi in proti njim se bom boril z mečem svojih ust.‹',
        17: 'Kdor ima uho, naj sliši, kaj Duh govori cerkvam: ›Tistemu, ki premaga, bom dal jesti od skrite mane in dal mu bom bel kamen in na kamnu napisano novo ime, ki ga ne pozna noben človek, razen, kdor ga prejme.‹«',
        18: '»In angelu cerkve v Tiatiri piši: ›Te stvari govori Božji Sin, ki ima svoje oči podobne plamenu ognja in so njegova stopala kakor čist bron;',
        19: 'poznam tvoja dela in ljubezen in služenje in vero in tvojo potrpežljivost in tvoja dela; in zadnjih je več kakor prvih.',
        20: 'Vendar imam zoper tebe nekaj stvari, ker trpiš to žensko Jezabelo, ki sebe imenuje prerokinjo, da uči in da zapeljuje moje služabnike, da zagrešijo prešuštvo in da jedo stvari, žrtvovane malikom.',
        21: 'In dal sem ji čas, da se pokesa od svojega prešuštvovanja, pa se ni pokesala.',
        22: 'Glej, vrgel jo bom na posteljo in te, ki z njo grešijo zakonolomstvo, v veliko stisko, razen če se ne pokesajo od svojih dejanj.',
        23: 'In njene otroke bom pobil s smrtjo in vse cerkve bodo vedele, da sem jaz tisti, ki preiskujem notranjosti in srca; in vsakemu od vas bom dal glede na vaša dejanja.',
        24: 'Toda tebi in ostalim iz Tiatire pravim, kdor nima tega nauka in tem, ki niso spoznali Satanovih globin, kakor govorijo; na vas ne bom nadel nobenega drugega bremena.',
        25: 'Temveč da trdno držite to, kar že imate, dokler ne pridem.',
        26: 'In kdor zmaga in moja dela ohrani do konca, njemu bom dal oblast nad narodi.',
        27: 'In vladal jim bo z železno palico; kakor lončena posoda bodo razbiti do črepinj; celo kot sem jaz prejel od svojega Očeta.',
        28: 'In dal mu bom jutranjo zvezdo.',
        29: 'Kdor ima uho, naj sliši, kaj Duh govori cerkvam.‹«',
    },
    3: {
        1: '»In angelu cerkve v Sardah piši: ›Te besede govori on, ki ima sedem Božjih Duhov in sedem zvezd; poznam tvoja dela, da imaš ime, da živiš, pa si mrtev.',
        2: 'Bodi oprezen in okrépi stvari, ki ostanejo, ki so pripravljene, da umro, kajti tvojih del nisem našel popolnih pred Bogom.',
        3: '§ Spomni se torej, kako si prejel in slišal in trdno drži ter se pokesaj. Če torej ne boš stražil, bom prišel nadte kakor tat in ne boš vedel, katero uro bom prišel nadte.',
        4: 'Nekaj imen imaš celó v Sardah, ki si niso omadeževali svojih oblek; in ti bodo hodili z menoj v belem, kajti vredni so.',
        5: 'Kdor premaga, ta isti bo oblečen v belo oblačilo in njegovega imena ne bom izbrisal iz knjige življenja, temveč bom njegovo ime priznal pred svojim Očetom in pred njegovimi angeli.',
        6: 'Kdor ima uho, naj sliši, kaj Duh govori cerkvam.‹«',
        7: '»In angelu cerkve v Filadelfiji piši: ›Te besede govori tisti, ki je svét, tisti, ki je resničen, tisti, ki ima Davidov ključ, tisti, ki odpira in noben človek ne zapira; in zapira, pa noben človek ne odpira.',
        8: 'Poznam tvoja dela. Glej, pred teboj sem postavil odprta vrata in noben človek jih ne more zapreti, kajti majhno moč imaš in ohranil si mojo besedo in nisi zanikal mojega imena.',
        9: 'Glej, prisilil bom te, iz Satanove shodnice, ki pravijo, da so Judje, pa niso, temveč lažejo; glej, prisilil jih bom, da pridejo in obožujejo pred tvojimi stopali in da spoznajo, da sem te vzljubil.',
        10: 'Ker si ohranil besedo moje potrpežljivosti, bom tudi jaz tebe obvaroval pred uro preizkušnje, ki bo prišla nad ves svet, da preizkusi tiste, ki prebivajo na zemlji.',
        11: 'Glej, pridem hitro. Trdno drži to, kar imaš, da ti noben človek ne odvzame tvoje krone.',
        12: 'Tistega, ki premaga, bom naredil [za] steber v templju svojega Boga in ne bo več šel ven; in nanj bom napisal ime svojega Boga in ime mesta svojega Boga, ki je novi Jeruzalem, ki prihaja dol z neba od mojega Boga in nanj bom napisal svoje novo ime.',
        13: 'Kdor ima uho, naj sliši, kaj Duh govori cerkvam.‹«',
        14: '»In angelu cerkve Laodikejcev piši: ›Te besede govori Amen, zvesta in resnična priča, začetek Božjega stvarstva;',
        15: 'poznam tvoja dela, da nisi niti mrzel niti vroč. Želim si, da bi bil mrzel ali vroč.',
        16: 'Zaradi tega, ker si mlačen in nisi niti mrzel niti vroč, te bom izpljunil iz svojih ust.‹',
        17: 'Ker praviš: ›Bogat sem in okrepil sem se z dobrinami in ne potrebujem ničesar;‹ pa ne veš, da si pomilovanja vreden in beden in reven in slep ter nag,',
        18: 'ti svetujem, da kupiš od mene zlata, prečiščenega v ognju, da boš lahko bogat in belo oblačilo, da boš lahko oblečen in da se ne prikaže sramota tvoje nagote in svoje oči mazili z mazilom za oči, da boš lahko videl.',
        19: '§ Kolikor jih imam rad, oštevam in karam. Bodi torej goreč in se pokesaj.',
        20: 'Glej, stojim pred vrati in trkam. Če katerikoli človek sliši moj glas in odpre vrata, bom vstopil k njemu in bom večerjal z njim in on z menoj.',
        21: 'Tistemu, ki premaga, bom zagotovil, da sede z menoj na moj prestol, celo kakor sem tudi sam zmagal in sem s svojim Očetom poseden na njegovem prestolu.',
        22: 'Kdor ima uho, naj sliši, kaj Duh govori cerkvam.‹«',
    },
    4: {
        1: 'Potem sem pogledal in glej, vrata na nebu so bila odprta in prvi glas, ki sem ga zaslišal, je bil, kakor bi bil od trobente, govoreče z menoj, ki je rekel: »Pridi sèm gor in pokazal ti bom stvari, ki morajo biti odslej.«',
        2: 'In takoj sem bil v duhu in glej, prestol je bil postavljen v nebesih in nekdo je sedel na prestolu.',
        3: 'In tisti, ki je sedel, je bil videti podoben kamnu jaspisu in sardiju in naokoli prestola je bila mavrica, na pogled podobna smaragdu.',
        4: 'In naokoli prestola je bilo štiriindvajset prestolov in na prestolih sem videl sedeti štiriindvajset starešin, oblečenih v bela oblačila in na svojih glavah so imeli zlate krone.',
        5: '§ In pred prestolom so izvirali bliski in grmenja ter glasovi; in pred prestolom je bilo sedem gorečih ognjenih svetilk, ki so sedem Božjih Duhov.',
        6: 'In pred prestolom je bilo stekleno morje, podobno kristalu; in v sredini prestola in naokoli prestola so bile štiri živali, spredaj in zadaj polne oči.',
        7: 'In prva žival je bila podobna levu in druga žival podobna teletu in tretja žival je imela obraz kakor človek, četrta žival pa je bila podobna letečemu orlu.',
        8: 'In štiri živali so imele vsaka izmed njih okoli sebe po šest peruti in znotraj so bile polne oči; in niso počivale dan in noč, rekoč: »Svet, svet, svet, Gospod Bog Vsemogočni, ki je bil in je in ki pride.«',
        9: 'In ko so te živali dale slavo in čast in zahvalo njemu, ki je sedel na prestolu, ki živi na veke vekov,',
        10: 'je štiriindvajset starešin padlo dol pred njim, ki je sedel na prestolu in oboževalo njega, ki živi na veke vekov in svoje krone vrglo pred prestol, rekoč:',
        11: '»Vreden si, oh Gospod, da prejmeš slavo in čast ter moč, kajti ustvaril si vse stvari in zaradi tvojega zadovoljstva so in so bile ustvarjene.«',
    },
    5: {
        1: 'In v desnici njega, ki je sedèl na prestolu, sem videl knjigo, popisano znotraj in na zadnji strani, zapečateno s sedmimi pečati.',
        2: 'In videl sem krepkega angela razglašati z močnim glasom: »Kdo je vreden, da odpre knjigo in da odtrga njene pečate?«',
        3: 'In nihče na nebu niti na zemlji niti pod zemljo, ni bil zmožen, da odpre knjigo niti, da pogleda nanjo.',
        4: 'In zelo sem jokal, ker se ni našel nihče vreden, da odpre in da bere knjigo niti, da pogleda nanjo.',
        5: 'In eden izmed starešin mi reče: »Ne jokaj; glej, Lev iz Judovega rodu, Davidova Korenina, je prevladal, da odpre knjigo in da razveže njenih sedem pečatov.«',
        6: '§ In pogledal sem in glej, na sredini prestola in štirih živali in sredi starešin je stalo Jagnje, kot bi bilo zaklano in je imelo sedem rogov in sedem oči, ki so sedem Božjih Duhov, poslanih po vsej zemlji.',
        7: 'In prišlo je ter vzelo knjigo iz desnice tistega, ki je sedel na prestolu.',
        8: 'In ko je vzelo knjigo, so štiri živali in štiriindvajset starešin padli dol pred Jagnjetom in vsi izmed njih so imeli harfe in zlate stekleničke, polne dišav, ki so molitve svetih.',
        9: 'In peli so novo pesem, rekoč: »Vredno si, da vzameš to knjigo in da odpreš njene pečate; kajti bilo si umorjeno in s svojo krvjo si nas odkupilo Bogu izmed vsakega sorodstva in jezika in ljudstva in naroda',
        10: '§ in si nas naredilo [za] kralje in duhovnike pri našemu Bogu, in mi bomo kraljevali na zemlji.«',
        11: 'In zagledal sem in zaslišal glas mnogih angelov naokoli prestola in živali in starešin, in njihovo število je bilo desettisočkrat deset tisoč in tisočev tisoči,',
        12: '§ ki so z močnim glasom govorili: »Vredno je Jagnje, ki je bilo zaklano, da prejme oblast in bogastva in modrost in moč in čast in slavo in blagoslov.«',
        13: '§ In vsako ustvarjeno bitje, ki je na nebu in na zemlji in pod zemljo in takšna, kot so v morju in vse, ki so v njem, sem slišal govoriti: »Blagoslov in čast in slava in oblast naj bo njemu, ki sedi na prestolu in Jagnjetu na veke vekov.«',
        14: '§ In štiri živali so rekle: »Amen.« In štiriindvajset starešin je padlo dol in oboževalo tistega, ki živi na veke vekov.',
    },
    6: {
        1: 'In potem sem videl, ko je Jagnje odprlo enega izmed pečatov in slišal sem, kakor bi bil hrup grmenja, eno izmed štirih živali govoriti: »Pridi in poglej.«',
        2: 'In videl sem ter zagledal belega konja; in tisti, ki je sedel na njem, je imel lok in dana mu je bila krona in odšel je naprej zmagovat in da zmaga.',
        3: 'In ko je odprlo drugi pečat, sem zaslišal drugo žival reči: »Pridi in poglej.«',
        4: '§ In odšel je drug konj, ki je bil rdeč; in tistemu, ki je sedel na njem, je bila dana oblast z zemlje odvzeti mir in da naj bi drug drugega klali, in dan mu je bil velik meč.',
        5: 'In ko je odprlo tretji pečat, sem zaslišal tretjo žival reči: »Pridi in poglej.« In pogledal sem in glej črn konj; in tisti, ki je sedel na njem, je imel v svoji roki tehtnico.',
        6: 'In zaslišal sem glas na sredini med štirimi živalmi reči: »Mera pšenice za kovanec in tri mere ječmena za kovanec; in glej, [da] ne škoduješ olju in vinu.«',
        7: 'In ko je odprlo četrti pečat, sem zaslišal glas četrte živali reči: »Pridi in poglej.«',
        8: '§ In pogledal sem in zagledal konja mrtvaško blede barve; in tistemu, ki je sedel na konju, je bilo ime Smrt in Pekel je sledil za njim. In izročena jima je bila oblast nad četrtino zemlje, da ubijata z mečem in z lakoto in s smrtjo in z zemeljskimi živalmi.',
        9: 'In ko je odprlo peti pečat, sem videl pod oltarjem duše teh, ki so bili zaklani zaradi Božje besede in zaradi pričevanja, ki so ga imeli',
        10: 'in z močnim glasom so vpili, rekoč: »Doklej, oh Gospod, svét in resničen, ne boš sodil in maščeval naše krvi na teh, ki prebivajo na zemlji?«',
        11: '§ In vsakemu izmed njih so bila dana bela svečana oblačila in rečeno jim je bilo, da naj še za kratek čas počivajo, dokler se ne bi izpolnili tudi njihovi soslužabniki in njihovi bratje, ki naj bi bili ubiti, kakor so bili oni sami.',
        12: 'In gledal sem, ko je odprlo šesti pečat in glej, bil je velik potres, in sonce je postalo črno kakor vrečevina iz dlak in luna je postala kakor kri,',
        13: 'in zvezde neba so popadale na zemljo, celo kakor figovo drevo odvrže svoje nezrele fige, ko ga stresa mogočen veter.',
        14: 'In nebo je odšlo kakor zvitek pergamenta, ko je zvit skupaj, in vsaka gora in otok sta bila premaknjena s svojega mesta.',
        15: 'Kralji zemlje, pomembni ljudje, bogataši, vrhovni poveljniki, mogočneži, vsak suženj in vsak prost človek pa so se skrili v brloge in v skale gorovij;',
        16: 'in rekli so goram in skalam: »Padite na nas in nas skrijte pred obrazom njega, ki sedi na prestolu in pred Jagnjetovim besom,',
        17: '§ kajti prišel je véliki dan njegovega besa in kdo bo zmožen obstati?«',
    },
    7: {
        1: 'In po teh stvareh sem zagledal štiri angele stati na štirih vogalih zemlje, ki so držali štiri vetrove zemlje, da veter ne bi pihal ne na zemljo, niti ne na morje, niti ne v nobeno drevo.',
        2: 'In videl sem drugega angela dvigovati se od vzhoda, ki je imel pečat živega Boga; in ta je z močnim glasom zaklical štirim angelom, ki jim je bilo dano, da škodujejo zemlji in morju,',
        3: 'rekoč: »Ne škodujte zemlji niti morju niti drevesom, dokler ne zapečatimo služabnikov našega Boga na njihovih čelih.«',
        4: 'In slišal sem število teh, ki so bili zapečateni. In zapečatenih je bilo sto štiriinštirideset tisoč izmed vseh rodov Izraelovih otrok.',
        5: 'Iz Judovega rodu je bilo zapečatenih dvanajst tisoč. Iz Rubenovega rodu je bilo zapečatenih dvanajst tisoč. Iz Gadovega rodu je bilo zapečatenih dvanajst tisoč.',
        6: 'Iz Aserjevega rodu je bilo zapečatenih dvanajst tisoč. Iz Neftálijevega rodu je bilo zapečatenih dvanajst tisoč. Iz Manásejevega rodu je bilo zapečatenih dvanajst tisoč.',
        7: 'Iz Simeonovega rodu je bilo zapečatenih dvanajst tisoč. Iz Lévijevega rodu je bilo zapečatenih dvanajst tisoč. Iz Isahárjevega rodu je bilo zapečatenih dvanajst tisoč.',
        8: 'Iz Zábulonovega rodu je bilo zapečatenih dvanajst tisoč. Iz Jožefovega rodu je bilo zapečatenih dvanajst tisoč. Iz Benjaminovega rodu je bilo zapečatenih dvanajst tisoč.',
        9: '§ Potem sem pogledal in glej, velika množica, ki je noben človek ne bi mogel prešteti, izmed vseh narodov in sorodstev in ljudi in jezikov, je stala pred prestolom in pred Jagnjetom, oblečena v bela svečana oblačila in [s] palmami v svojih rokah',
        10: 'in vpila z močnim glasom, rekoč: »Rešitev duš našemu Bogu, ki sedi na prestolu in Jagnjetu.«',
        11: 'In vsi angeli so stali naokrog prestola in okoli starešin in štirih živali in pred prestolom so padli na svoje obraze in oboževali Boga,',
        12: '§ rekoč: »Amen: ›Blagoslov, slava, modrost, zahvaljevanje, čast, oblast in moč bodi našemu Bogu na veke vekov. Amen.‹«',
        13: '§ In eden izmed starešin je odgovoril ter mi rekel: »Kaj so ti, ki so oblečeni v bela svečana oblačila? In od kod so prišli?«',
        14: '§ In rekel sem mu: »Gospod, ti veš.« In rekel mi je: »To so tisti, ki so prišli iz velike stiske in so oprali svoja svečana oblačila in jih pobelili v Jagnjetovi krvi.',
        15: '§ Zato so pred Božjim prestolom in v njegovem templju mu služijo dan in noč. In tisti, ki sedi na prestolu, bo prebival med njimi.',
        16: 'Ne bodo več lačni, niti ne več žejni, niti nanje ne bo svetilo sonce, niti nobena vročina.',
        17: 'Kajti Jagnje, ki je v sredi prestola, jih bo paslo in jih vodilo k živim studencem vodá in Bog bo obrisal vse solze z njihovih oči.«',
    },
    8: {
        1: 'In ko je odprlo sedmi pečat, je bila na nebu kake pol ure tišina.',
        2: 'In videl sem sedem angelov, ki so stali pred Bogom in tem je bilo danih sedem trobent.',
        3: 'In prišel je drug angel in stal pred oltarjem, ki je imel zlato kadilnico in dano mu je bilo veliko kadila, da bi ga z molitvami vseh svetih daroval na zlatem oltarju, ki je bil pred prestolom.',
        4: 'In dim kadila, ki je prišel z molitvami svetih, se je iz angelove roke dvignil pred Boga.',
        5: 'In angel je vzel kadilnico in jo napolnil z ognjem z oltarja in jo vrgel v zemljo; in tam so bili glasovi, grmenja, bliski in potres.',
        6: 'In sedem angelov, ki so imeli sedem trobent, se je pripravilo, da zatrobijo.',
        7: '§ Zatrobil je prvi angel in sledila sta toča in ogenj, pomešana s krvjo in bila sta vržena na zemljo, in zgorela je tretjina dreves in zgorela je vsa zelena trava.',
        8: 'In zatrobil je drugi angel in kakor bi bila velika gora, ki je gorela z ognjem, vržena v morje, in tretjina morja je postala kri,',
        9: '§ in tretjina ustvarjenih bitij, ki so bila v morju in so imela življenje, je poginila, in uničena je bila tretjina ladij.',
        10: 'In zatrobil je tretji angel in z neba je padla velika zvezda, goreča, kot bi bila svetilka in ta je padla na tretjino rek in na studence vodá;',
        11: 'in zvezda se je imenovala Pelin, in tretjina vodá je postala grenka; in mnogo ljudi je umrlo zaradi vodá, ker so postale grenke.',
        12: 'In zatrobil je četrti angel in udarjena je bila tretjina sonca in tretjina lune in tretjina zvezd, tako kot bi njihova tretjina potemnela in dan ni sijal za svojo tretjino in prav tako noč.',
        13: '§ In gledal sem in slišal angela leteti po sredi neba, rekoč z močnim glasom: »Gorje, gorje, gorje prebivalcem zemlje zaradi preostalih glasov trobente treh angelov, ki bodo še zatrobili!«',
    },
    9: {
        1: '§ In zatrobil je peti angel in videl sem zvezdo pasti z neba na zemljo in dan mu je bil ključ od jame brez dna.',
        2: 'In odprl je jamo brez dna in iz jame se je dvignil dim kakor dim velike talilne peči; in zaradi dima iz jame sta potemnela sonce in zrak.',
        3: 'In iz dima so prišle na zemljo kobilice in dana jim je bila oblast, kakor imajo škorpijoni oblast na zemlji.',
        4: 'In naročeno jim je bilo, da naj ne bi škodili zemeljski travi niti nobeni zeleni stvari niti nobenemu drevesu, temveč samo tistim ljudem, ki na svojih čelih nimajo Božjega pečata.',
        5: 'In dano jim je bilo, da naj jih ne bi pobijale, temveč da naj bi bili pet mesecev mučeni, in njihovo mučenje je bilo kakor mučenje škorpijona, ko piči človeka.',
        6: 'In v tistih dneh bodo ljudje iskali smrt, pa je ne bodo našli; in želeli bodo umreti, smrt pa bo bežala od njih.',
        7: 'In oblika kobilic je bila podobna konjem, pripravljenim za boj; in na njihovih glavah so bile, kot bi bile krone podobne zlatu in njihovi obrazi so bili kakor človeški obrazi.',
        8: 'In imele so lase kakor ženski lasje in njihovi zobje so bili kakor levji zobje.',
        9: 'In imele so prsne oklepe, kot bi bili prsni oklepi iz železa; in zvok njihovih peruti je bil kakor zvok bojnih voz z mnogimi konji, drvečimi v boj.',
        10: 'In imele so repe kot škorpijoni in na njihovih repih so bila žela; in njihova oblast je bila pet mesecev škoditi ljudem.',
        11: 'In nad seboj so imele kralja, ki je angel iz jame brez dna, katerega ime je v hebrejskem jeziku Ábadon, toda v grškem jeziku ima svoje ime Apolíon.',
        12: 'Eno gorje je minilo, in glej, zatem pride še dvoje gorje.',
        13: 'In zatrobil je šesti angel in od zlatega oltarja, ki je pred Bogom, sem zaslišal glas iz štirih rogov,',
        14: 'rekoč šestemu angelu, ki je imel trobento: »Odveži štiri angele, ki so zvezani v veliki reki Evfrat.«',
        15: 'In štirje angeli, ki so bili pripravljeni na to uro in dan in mesec in leto, so bili odvezani, da pobijejo tretjino ljudi.',
        16: 'In število vojske jezdecev je bilo dvesto milijonov; in slišal sem njihovo število.',
        17: '§ In tako sem v videnju videl konje in te, ki so sedeli na njih, da imajo prsni oklepi [barvo] ognja in hijacinta ter žvepla; in glave konj so bile kakor levje glave, in iz njihovih ust so prihajali ogenj in dim in žveplo.',
        18: 'Od teh treh je bila tretjina ljudi ubita z ognjem, z dimom in z žveplom, ki so prihajali iz njihovih ust.',
        19: 'Kajti njihova oblast je v njihovih ustih in v njihovih repih, kajti njihovi repi so bili podobni kačam in imeli so glave in z njimi škodujejo.',
        20: '§ In preostali izmed ljudi, ki niso bili pobiti s temi nadlogami, se še niso pokesali od del svojih rok, da ne bi oboževali hudičev, zlatih malikov, srebrnih in bronastih, kamnitih in lesenih, ki niti ne morejo videti, niti slišati, niti hoditi;',
        21: 'niti se niso pokesali od svojih umorov, niti od svojih čarodejstev, niti od svojih prešuštvovanj, niti od svojih tatvin.',
    },
    10: {
        1: 'In videl sem drugega mogočnega angela priti dol z neba, oblečenega z oblakom, in nad njegovo glavo je bila mavrica in njegov obraz je bil, kakor bi bil sonce in njegova stopala kakor ognjeni stebri.',
        2: 'In v svoji roki je imel odprto majhno knjigo; in svoje desno stopalo je postavil na morje, svoje levo stopalo pa na zemljo',
        3: 'ter zavpil z močnim glasom, kot kadar rjove lev. In ko je zavpil, je sedem gromov izustilo svoje glasove.',
        4: 'In ko je sedem gromov izustilo svoje glasove, sem bil na tem, da napišem. Zaslišal pa sem glas iz nebes, ki mi je rekel: »Zapečati te besede, ki jih je spregovorilo sedem gromov in jih ne zapiši.«',
        5: 'In angel, ki sem ga videl stati na morju in na zemlji, je svojo roko vzdignil k nebu',
        6: 'in prisegel pri njem, ki živi na veke vekov, ki je ustvaril nebo in stvari, ki so na njem in zemljo in stvari, ki so na njej in morje in stvari, ki so v njem, da naj ne bi bilo več časa,',
        7: 'toda v dneh glasu sedmega angela, ko bo ta začel trobiti, naj bi se dokončala Božja skrivnost, kakor jo je razglasil svojim služabnikom prerokom.',
        8: 'In glas, ki sem ga slišal z neba, mi je ponovno spregovoril ter rekel: »Pojdi in vzemi majhno knjigo, ki je odprta v roki angela, ki stoji na morju in na zemlji.«',
        9: 'In odšel sem k angelu ter mu rekel: »Daj mi majhno knjigo.« In rekel mi je: »Vzemi jo in jo pojej, in tvoj trebuh bo naredila grenek, toda v tvojih ustih bo sladka kakor med.«',
        10: 'In iz angelove roke sem vzel majhno knjigo in jo pojedel in v mojih ustih je bila sladka kakor med in takoj, ko sem jo pojedel, je bil moj trebuh grenek.',
        11: 'In rekel mi je: »Ponovno moraš prerokovati pred mnogimi ljudmi, narodi, jeziki in kralji.«',
    },
    11: {
        1: '§ In dan mi je bil trst, podoben palici in angel je stal, rekoč: »Vstani in izmeri Božji tempelj in oltar in te, ki v njem obožujejo.',
        2: 'Toda dvor, ki je zunaj templja, izpusti in ga ne izmeri, kajti dan je poganom in dvainštirideset mesecev bodo pod stopali pohojali sveto mesto.',
        3: 'In svojima dvema pričama bom dal oblast in prerokovala bosta tisoč dvesto in šestdeset dni, oblečeni v vrečevino.«',
        4: 'To sta dve oljki in dva svečnika, ki stojita pred Bogom zemlje.',
        5: 'In če jima bo katerikoli človek škodil, iz njunih ust izide ogenj in požre njune sovražnike. Če pa ju bo katerikoli človek poškodoval, mora biti na ta način ubit.',
        6: 'Ta [dva] imata oblast, da zapreta nebo, da v dneh njunega prerokovanja ne dežuje in oblast imata nad vodami, da jih spremenita v kri, zemljo pa udarita z vsemi nadlogami, tako pogosto, kakor hočeta.',
        7: 'In ko bosta končala svoje pričevanje, se bo iz jame brez dna povzpel zvernik, ki bo povzročil vojno proti njima in ju premagal ter ju ubil.',
        8: 'Njuni trupli pa bosta ležali na ulici velikega mesta, ki se mu duhovno reče Sódoma in Egipt, kjer je bil križan tudi naš Gospod.',
        9: 'In tisti izmed ljudi in sorodstev in jezikov in narodov bodo tri dni in pol gledali njuni trupli in ne bodo pustili, da bi bili njuni trupli položeni v grobova.',
        10: 'In tisti, ki prebivajo na zemlji, se bodo veselili nad njima in se zabavali ter bodo drug drugemu pošiljali darila, ker sta ta dva preroka mučila te, ki prebivajo na zemlji.',
        11: 'Po treh dneh in pol pa je vanju vstopil Duh življenja od Boga in vstala sta na svoja stopala in na te, ki so ju videli, je padel velik strah.',
        12: 'In zaslišala sta močan glas z neba, ki jima je rekel: »Pridita sèm gor.« In v oblaku sta se vzpela do neba, njuni sovražniki pa so ju gledali.',
        13: 'In isto uro je bil tam velik potres in padel je deseti del mesta in v potresu jih je bilo izmed ljudi umorjenih sedem tisoč; preostanek pa je bil zgrožen in dal slavo Bogu nebes.',
        14: 'Drugo gorje je minilo in glej, hitro pride tretje gorje.',
        15: '§ In zatrobil je sedmi angel in na nebu so bili močni glasovi, govoreč: »Kraljestva tega sveta so postala kraljestva našega Gospoda in njegovega Kristusa in vladal bo na veke vekov.«',
        16: 'In štiriindvajset starešin, ki so na svojih sedežih sedeli pred Bogom, je padlo na svoje obraze ter oboževalo Boga,',
        17: '§ rekoč: »Zahvaljujemo se ti, oh Gospod Bog Vsemogočni, ki si in si bil in boš prišel, ker si si vzel svojo veliko oblast in si zakraljeval.',
        18: 'In narodi so bili jezni in prišel je tvoj bes in čas mrtvih in da bi jim bilo sojeno in da bi dal nagrado svojim služabnikom prerokom in svetim ter tem, ki se bojijo tvojega imena, majhnim in velikim, in da bi uničil te, ki uničujejo zemljo.«',
        19: 'In na nebu se je odprl Božji tempelj in v njegovem templju je bilo videti skrinjo njegove zaveze; in bili so bliski in glasovi in grmenja in potres in velika toča.',
    },
    12: {
        1: 'In na nebu se je prikazalo veliko znamenje; ženska, oblečena s soncem in luna pod njenimi stopali in krona dvanajsterih zvezd na njeni glavi.',
        2: 'In ona, ki je bila z otrokom, je vpila v porodnih mukah in bolečinah, da bi rodila.',
        3: 'In na nebu se je prikazalo drugo znamenje in glej, velik rdeč zmaj, ki je imel sedem glav in deset rogov ter na njegovih glavah sedem kron.',
        4: 'In njegov rep je potegnil z neba tretjino zvezd ter jih vrgel na zemljo in zmaj je stal pred žensko, ki je bila pripravljena, da rodi, da bi požrl njenega otroka takoj, ko bi se rodil.',
        5: 'In rodila je fantka, ki je bil [namenjen], da vsem narodom vlada z železno palico in njen otrok je bil vzet k Bogu in k njegovemu prestolu.',
        6: 'In ženska je pobegnila v divjino, kjer je imela prostor, pripravljen od Boga, da naj bi jo tam hranili tisoč dvesto in šestdeset dni.',
        7: 'In bila je vojna v nebesih. Mihael in njegovi angeli so se bojevali proti zmaju in zmaj se je bojeval ter njegovi angeli,',
        8: 'pa niso prevladali niti se na nebu zanje ni več našel prostor.',
        9: 'In véliki zmaj je bil vržen ven, ta stara kača, imenovana hudič in Satan, ki zavaja ves svet. Izgnan je bil na zemljo in njegovi angeli so bili izgnani z njim.',
        10: 'In na nebu sem zaslišal močan glas, rekoč: »Sedaj je prišla rešitev duš in moč in kraljestvo našega Boga in oblast njegovega Kristusa, kajti vržen je dol obtoževalec naših bratov, ki jih je dan in noč obtoževal pred našim Bogom.«',
        11: 'In oni so ga premagali s krvjo Jagnjeta in z besedo svojega pričevanja in svojih življenj niso ljubili do smrti.',
        12: 'Zato se veselite, ve nebesa in vi, ki prebivate v njih. Gorje prebivalcem zemlje in morja! Kajti hudič je prišel dol k vam, zelo ogorčen, ker ve, da ima le malo časa.',
        13: 'In ko je zmaj videl, da je bil vržen na zemljo, je preganjal žensko, ki je rodila moško dete.',
        14: 'In ženski sta bili dani dve peruti velikega orla, da bi lahko odletela v divjino, na njen kraj, kjer je bila hranjena čas in čase in polovico časa, proč od obraza kače.',
        15: 'In kača je iz svojih ust vrgla za žensko vodo kot poplavo, da bi lahko povzročila, da jo poplava odnese.',
        16: 'In zemlja je pomagala ženski in zemlja je odprla svoja usta ter požrla poplavo, ki jo je zmaj vrgel iz svojih ust.',
        17: 'In zmaj je bil ogorčen proti ženski in odšel, da povzroči vojno proti preostanku njenega potomstva, ki se drži Božjih zapovedi in ima pričevanje Jezusa Kristusa.',
    },
    13: {
        1: '§ In stal sem na morskem pesku in videl zvernika dvigniti se iz morja, ki je imel sedem glav ter deset rogov in na svojih rogovih deset kron in na svojih glavah bogokletno ime.',
        2: 'In zvernik, ki sem ga videl, je bil podoben leopardu in njegova stopala so bila kakor medvedja stopala in njegova usta kakor levja usta. In zmaj mu je dal svojo moč in svoj prestol ter veliko oblast.',
        3: 'In videl sem eno izmed njegovih glav, kot bi bila ranjena do smrti in njegova smrtna rana je bila ozdravljena in ves svet se je spraševal o zverniku.',
        4: 'In oboževali so zmaja, ki je dal oblast zverniku in oboževali so zvernika, rekoč: »Kdo je podoben zverniku? Kdo se je zmožen bojevati z njim?«',
        5: 'In dana so mu bila usta, ki so govorila velike stvari ter bogokletja in dana mu je bila oblast, da nadaljuje dvainštirideset mesecev.',
        6: 'In svoja usta je odprl v bogokletju proti Bogu, da preklinja njegovo ime in njegovo šotorsko svetišče in te, ki prebivajo v nebesih.',
        7: 'In dano mu je bilo, da se vojskuje s svetimi in da jih premaga in dana mu je bila oblast nad vsemi sorodstvi in jeziki in narodi.',
        8: 'In oboževali ga bodo vsi, ki prebivajo na zemlji, katerih imena že od ustanovitve sveta niso zapisana v knjigi življenja zaklanega Jagnjeta.',
        9: 'Če ima katerikoli človek uho, naj sliši.',
        10: '§ Kdor vodi v ujetništvo, bo šel v ujetništvo. Kdor ubija z mečem, mora biti ubit z mečem. Tukaj je potrpežljivost in vera svetih.',
        11: 'In zagledal sem še enega zvernika prihajati gor iz zemlje in imel je dva rogova, podobna jagnjetovim, govoril pa je kakor zmaj.',
        12: 'In izvajal je vso oblast prvega zvernika pred njim in povzroča zemlji in tistim, ki prebivajo na njej, da obožujejo prvega zvernika, katerega smrtna rana se je pozdravila.',
        13: 'In dela velike čudeže, tako da naredi pred očmi ljudi, da pride ogenj z neba na zemljo',
        14: 'in zavaja te, ki prebivajo na zemlji, s pomočjo teh čudežev, za katere je imel oblast, da jih je delal pred očmi zvernika, rekoč tistim, ki prebivajo na zemlji, da bi morali narediti podobo zvernika, ki je imel rano od meča in je oživel.',
        15: 'In imel je moč, da dá življenje podobi zvernika, da naj bi podoba zvernika tako govorila kakor povzročila, da naj bi bili pobiti vsi, ki ne bi oboževali podobe zvernika.',
        16: 'In povzroči vsem, tako malim kakor velikim, bogatim in revnim, svobodnim in sužnjem, da sprejmejo znamenje v svojo desnico ali v svoja čela',
        17: 'in da noben človek ne bi smel kupovati ali prodajati, razen, kdor je imel znamenje ali ime zvernika ali število njegovega imena.',
        18: 'Tukaj je modrost. Naj tisti, ki ima razum, prešteje število zvernika; kajti to je število človeka in njegovo število je šeststo šestinšestdeset.',
    },
    14: {
        1: '§ In pogledal sem in glej, Jagnje je stalo na gori Sion in z njim sto štiriinštirideset tisoč [tistih], ki so imeli na svojih čelih napisano ime njihovega Očeta.',
        2: 'In zaslišal sem glas z neba, kakor glas mnogih vodá in kakor glas velikega groma in slišal sem glas harfistov igrati s svojimi harfami',
        3: 'in peli so, kakor bi bila to nova pesem, pred prestolom in pred štirimi živalmi in starešinami in noben človek se ni mogel naučiti te pesmi razen sto štiriinštiridesetih tisočev, ki so bili odkupljeni z zemlje.',
        4: 'To so tisti, ki niso bili omadeževani z ženskami, kajti deviški so. To so tisti, ki sledijo Jagnjetu, kamorkoli gre. Ti so bili odkupljeni izmed ljudi, so prvi sadovi Bogu in Jagnjetu.',
        5: '§ In v njihovih ustih ni bilo najti zvijače, kajti pred Božjim prestolom so brez krivde.',
        6: 'In videl sem drugega angela leteti po sredi neba, ki je imel večen evangelij, da ga oznani tem, ki prebivajo na zemlji in vsakemu narodu, sorodstvu, jeziku in ljudem,',
        7: 'govoreč z močnim glasom: »Bojte se Boga in dajte mu slavo, kajti prišla je ura njegove sodbe; in obožujte njega, ki je naredil nebo in zemljo in morje ter studence vodá.«',
        8: 'In sledil je še en angel, govoreč: » [Metropola] Babilon je padla, padla je, ta velika metropola, zato ker je vse narode prisilila piti od vina besa svojega prešuštvovanja.«',
        9: 'In tema je sledil še tretji angel, govoreč z močnim glasom: »Če katerikoli človek obožuje zvernika in njegovo podobo ter v svoje čelo ali v svojo roko sprejme njegovo znamenje,',
        10: '§ bo ta isti pil od vina Božjega besa, ki je brez mešanja izlit v čašo njegovega ogorčenja in v prisotnosti svetih angelov in v Jagnjetovi prisotnosti bo mučen z ognjem in žveplom',
        11: 'in dim njihovega mučenja se vzpenja na veke vekov in ne podnevi ne ponoči nima počitka, kdor obožuje zvernika ter njegovo podobo in kdorkoli sprejme znamenje njegovega imena.',
        12: 'Tukaj je potrpežljivost svetih; tukaj so tisti, ki se držijo Božjih zapovedi in Jezusove vere.«',
        13: 'In zaslišal sem glas z neba, ki mi je rekel: »Zapiši: ›Blagoslovljeni so mrtvi, ki odslej umrejo v Gospodu.‹ ›Da,‹ govori Duh, ›da se lahko odpočijejo od svojih naporov; in njihova dela jim sledijo.‹«',
        14: 'In pogledal sem ter zagledal bel oblak in na oblaku sedeti nekoga, podobnega Sinu človekovemu, ki ima na svoji glavi zlato krono in v svoji roki oster srp.',
        15: 'In iz templja je prišel drug angel in tistemu, ki je sedel na oblaku, je z močnim glasom zaklical: »Zamahni s svojim srpom in požanji, kajti zate je prišel čas, da žanješ; kajti žetev zemlje je dozorela.«',
        16: 'In tisti, ki je sedèl na oblaku, je s svojim srpom zamahnil po zemlji in zemlja je bila požeta.',
        17: 'In drug angel je prišel iz templja, ki je v nebesih, ki je tudi imel oster srp.',
        18: 'In drug angel je prišel od oltarja, ki je imel oblast nad ognjem in z glasnim krikom je zaklical tistemu, ki je imel oster srp, rekoč: »Zamahni s svojim ostrim srpom in zberi zemeljske trtne grozde, kajti njeno grozdje je popolnoma dozorelo.«',
        19: 'In angel je s svojim srpom zamahnil po zemlji in zbral vino zemlje in ga vrgel v veliko vinsko stiskalnico Božjega besa.',
        20: 'In vinska stiskalnica je bila pohojana zunaj mesta in iz vinske stiskalnice je prišla kri, celó konjem do uzd, tisoč in šeststo dolžin brazd daleč.',
    },
    15: {
        1: 'In na nebu sem videl drugo znamenje, veliko in čudovito, sedem angelov, ki so imeli sedem zadnjih nadlog, kajti z njimi je dopolnjen Božji bes.',
        2: 'In videl sem, kot bi bilo stekleno morje, pomešano z ognjem; in ti, ki so dosegli zmago nad zvernikom in nad njegovo podobo in nad njegovim znamenjem in nad številom njegovega imena, so z Božjimi harfami stali na steklenem morju.',
        3: 'In peli so pesem Božjega služabnika Mojzesa in Jagnjetovo pesem, rekoč: »Velika in čudovita so tvoja dela, Gospod Bog Vsemogočni; tvoje poti so pravične in resnične, ti Kralj svetih.',
        4: 'Kdo se te ne bi bal, oh Gospod in ne proslavil tvojega imena? Kajti samo ti si svet, kajti vsi narodi bodo prišli in oboževali pred teboj, kajti tvoje sodbe so postale očitne.«',
        5: 'In nató sem pogledal in glej, tempelj šotorskega svetišča pričevanja v nebesih je bil odprt.',
        6: 'In iz templja je prišlo sedem angelov, ki so imeli sedem nadlog, oblečenih v čisto in belo platno in preko prsi, opasanih z zlatimi pasovi.',
        7: 'In ena izmed štirih živali je dala sedmim angelom sedem zlatih stekleničk, polnih besa Boga, ki živi na veke vekov.',
        8: '§ In tempelj je bil napolnjen z dimom od Božje slave in od njegove moči in noben človek ni bil sposoben vstopiti v tempelj, dokler se ne bi izpolnile sedmere nadloge sedmih angelov.',
    },
    16: {
        1: 'In iz templja sem zaslišal močan glas, ki je sedmim angelom rekel: »Pojdite po svojih poteh in na zemljo izlijte stekleničke Božjega besa.«',
        2: 'In odšel je prvi in svojo stekleničko izlil na zemljo; in na ljudi, ki so imeli znamenje zvernika in na tiste, ki so oboževali njegovo podobo, je padlo ogabno in boleče vnetje.',
        3: 'In drugi angel je svojo stekleničko izlil na morje in postalo je kakor kri mrtvega človeka in vsaka živa duša v morju je umrla.',
        4: 'In tretji angel je svojo stekleničko izlil v reke in studence vodá; in postale so kri.',
        5: 'In slišal sem reči angela vodá: »Ti si pravičen, oh Gospod, ki si in si bil in boš, ker si tako sodil.',
        6: 'Kajti prelili so kri svetih in prerokov in dal si jim piti kri, kajti zaslužili so.«',
        7: 'In od oltarja sem nekoga slišal reči: »Točno tako, Gospod Bog Vsemogočni, resnične in pravične so tvoje sodbe.«',
        8: 'In četrti angel je svojo stekleničko izlil na sonce in dana mu je bila oblast, da z ognjem žge ljudi.',
        9: 'In ljudje so bili žgani z veliko vročino in izrekali bogokletje proti imenu Boga, ki ima oblast nad temi nadlogami, pa se niso pokesali, da bi mu dali slavo.',
        10: 'In peti angel je svojo stekleničko izlil na zvernikov prestol in njegovo kraljestvo je bilo polno teme in zaradi bolečine so si grizli svoje jezike',
        11: 'in zaradi svojih bolečin in svojih vnetij so izrekali bogokletje proti Bogu nebes in se niso pokesali od svojih dejanj.',
        12: 'In šesti angel je svojo stekleničko izlil na veliko reko Evfrat in njena voda se je posušila, da bi se lahko pripravila pot kraljem z vzhoda.',
        13: 'In videl sem iz ust zmaja in iz ust zvernika ter iz ust lažnega preroka priti tri nečiste duhove, podobne žabam.',
        14: 'Kajti to so duhovi hudičev, ki delajo čudeže, ki gredo do kraljev zemlje celotnega sveta, da jih zberejo na bitko tistega vélikega dne Boga Vsemogočnega.',
        15: '»Glej, pridem kakor tat. Blagoslovljen je, kdor straži in obdrži svoje obleke, da ne bi hodil nag in bi videli njegovo sramoto.«',
        16: 'In zbral jih je skupaj na kraju, v hebrejskem jeziku imenovanem Harmagedón.',
        17: 'In sedmi angel je svojo stekleničko izlil v zrak in iz nebeškega templja je prišel od prestola močan glas, rekoč: »Narejeno je.«',
        18: 'In tam so bili glasovi in gromi in bliski in bil je velik potres, kakršnega še ni bilo, odkar so bili na zemlji ljudje, tako mogočen potres in tako velik.',
        19: 'In veliko mesto je bilo razdeljeno na tri dele in mesta narodov so se podrla in vélika [metropola] Babilon je prišla v spomin pred Boga, da ji da čašo vina okrutnosti svojega besa.',
        20: 'In vsak otok je zbežal proč in gorá ni bilo najti.',
        21: 'In z neba je padala na ljudi velika toča, vsak kamen težak okoli talent in ljudje so zaradi nadloge toče izrekali bogokletje proti Bogu; kajti nadloga od tega je bila silno velika.',
    },
    17: {
        1: 'In prišel je eden izmed sedmih angelov, ki so imeli sedem stekleničk in govoril z menoj ter mi rekel: »Pridi sèm, pokazal ti bom sodbo vélike vlačuge, ki sedi nad mnogimi vodami,',
        2: 's katero so kralji zemlje zagrešili prešuštvovanje, prebivalci zemlje pa so bili opiti z vinom njenega prešuštvovanja.«',
        3: 'Tako me je v duhu odvedel proč v divjino in videl sem žensko sedeti na škrlatno obarvanem zverniku, polnem imen bogokletstev, ki je imel sedem glav in deset rogov.',
        4: 'In ženska je bila oblečena v vijolično in škrlatno [rdečo] barvo in odeta z zlatom in dragocenimi kamni in biseri in v svoji roki je imela zlato čašo polno ogabnosti in umazanosti svojega prešuštvovanja',
        5: 'in na njenem čelu je bilo napisano ime: SKRIVNOST, VÉLIKA [METROPOLA] BABILON, MATI POCESTNIC IN OGABNOSTI ZEMLJE.',
        6: 'In videl sem žensko, pijano s krvjo svetih in s krvjo Jezusovih mučencev in ko sem jo zagledal, sem se čudil z veliko osuplostjo.',
        7: 'Angel pa mi je rekel: »Zakaj se čudiš? Povedal ti bom skrivnost ženske in zvernika, ki jo prenaša, ki ima sedem glav in deset rogov.',
        8: 'Zvernik, ki si ga videl, je bil in ga ni in vzpel se bo iz jame brez dna in šel v pogubo in tisti, ki prebivajo na zemlji, katerih imena od ustanovitve sveta niso bila zapisana v knjigi življenja, se bodo čudili, ko bodo gledali zvernika, ki je bil in ga ni, pa vendar je.',
        9: 'In tukaj je um, ki ima modrost. Sedem glav je sedem gorá, na katerih sedi ženska.',
        10: 'In tam je sedem kraljev; pet je padlih in eden je, drugi pa še ni prišel; ko pa pride, mora kratek čas nadaljevati.',
        11: 'Zvernik pa, ki je bil in ga ni, je celó osmi in je izmed sedmih in gre v pogubo.',
        12: 'In deset rogov, ki si jih videl, je deset kraljev, ki doslej še niso prejeli kraljestva, toda kot kralji prejmejo oblast z zvernikom za eno uro.',
        13: 'Ti imajo en um, svojo oblast in moč pa bodo dali zverniku.',
        14: 'Ti se bodo vojskovali z Jagnjetom, Jagnje pa jih bo premagalo, kajti on je Gospod gospodov in Kralj kraljev in tisti, ki so z njim, so poklicani in izbrani in zvesti.«',
        15: 'In rekel mi je: »Te vode, ki jih vidiš, kjer sedi vlačuga, so ljudje in množice in narodi in jeziki.',
        16: '§ In deset rogov, ki si jih videl na zverniku, ti bodo sovražili vlačugo in naredili jo bodo opustošeno in nago in jedli bodo njeno meso ter jo sežgali z ognjem.',
        17: 'Kajti Bog je na njihova srca položil, da izpolnijo njegovo voljo in da se strinjajo in svoje kraljestvo izročijo zverniku, dokler ne bodo izpolnjene Božje besede.',
        18: 'Ženska pa, ki si jo videl, je to veliko mesto, ki kraljuje nad kralji zemlje.«',
    },
    18: {
        1: 'In po teh stvareh sem videl drugega angela priti dol z neba, ki je imel veliko oblast in zemlja je bila razsvetljena z njegovo slavo.',
        2: 'In mogočno je vpil z močnim glasom, rekoč: »Vélika [metropola] Babilon je padla, padla je in postala prebivališče hudičev in ječa vsakega nečistega duha in kletka vsake nečiste in osovražene ptice.',
        3: '§ Kajti vsi narodi so pili od vina besa njenega prešuštvovanja in kralji zemlje so z njo zagrešili prešuštvovanje in trgovci zemlje so obogateli od obilja njenih poslastic.«',
        4: 'In zaslišal sem drug glas z neba, rekoč: »Pridite iz nje, moji ljudje, da ne boste soudeleženi z njenimi grehi in da ne prejmete od njenih nadlog.',
        5: 'Kajti njeni grehi so segli do neba in Bog se je spomnil njenih krivičnosti.',
        6: 'Nagradite jo, kakor vas je sama nagradila in podvojite ji dvojno glede na njena dela; v čašo, ki jo je napolnila, ji napolnite dvojno.',
        7: 'Kolikor je samo sebe slavila in slastno živela, toliko muk in bridkosti ji dajte, kajti v svojem srcu pravi: ›Sedim kraljica in nisem vdova in ne bom videla bridkosti.‹',
        8: 'Zatorej bodo njene nadloge prišle v enem dnevu; smrt in žalovanje in lakota in popolnoma bo požgana z ognjem, kajti močan je Gospod Bog, ki jo sodi.«',
        9: 'In kralji zemlje, ki so zagrešili prešuštvovanje in z njo slastno živeli, jo bodo objokovali in žalovali za njo, ko bodo videli dim njenega gorenja,',
        10: 'stoječ daleč stran zaradi strahu pred njenim mučenjem, rekoč: »Ojoj, ojoj, ta vélika metropola Babilon, ta mogočna metropola! Kajti v eni uri je prišla tvoja sodba.«',
        11: 'In trgovci zemlje bodo jokali in žalovali nad njo, kajti noben človek ne kupuje več njihovega trgovskega blaga,',
        12: 'trgovskega blaga iz zlata in srebra in dragocenih kamnov in iz biserov in tankega lanenega platna in bagra in svile in škrlata in vsakega dišečega lesa in vseh vrst posod iz slonovine in vseh vrst posod iz najdragocenejšega lesa in iz brona in železa in marmorja',
        13: '§ in cimeta in dišav in mazil in kadil in vina in olja in fine moke in pšenice in živali in ovc in konj in bojnih vozov in sužnjev in človeških duš.',
        14: '§ In sadeži, po katerih je hlepela tvoja duša, so odšli od tebe in vse stvari, ki so bile okusne in lepe, so odšle od tebe in sploh jih ne boš več našel.',
        15: 'Trgovci s temi stvarmi, ki so po njej obogateli, bodo zaradi strahu pred njenimi mukami stali daleč stran ter jokali in tarnali',
        16: 'in govorili: »Ojoj, ojoj, ta vélika metropola, ki je bila oblečena v tanko laneno platno in bager in škrlat in odeta z zlatom in dragocenimi kamni in biseri!',
        17: '§ Kajti v eni uri pridejo v nič tako velika bogastva.« In vsak kapitan in vse spremstvo na ladjah in mornarji in kolikor jih trguje po morju, so stali daleč stran',
        18: 'in ko so zagledali dim njenega gorenja, so vpili, rekoč: »Katero mesto je podobno tej véliki metropoli!«',
        19: '§ In na svoje glave so metali prah in vpili, jokali in tarnali, rekoč: »Ojoj, ojoj, ta vélika metropola, v kateri so zaradi njene visoke cene postali bogati vsi, ki so imeli ladje na morju! Kajti v eni uri je postala opustošena.',
        20: 'Veselite se nad njo, ve nebesa in vi sveti apostoli ter preroki, kajti Bog vas je maščeval na njej.«',
        21: 'In mogočen angel je pobral kamen, podoben velikemu mlinskemu kamnu in ga vrgel v morje, rekoč: »Tako bo ta vélika metropola Babilon z nasiljem zrušena in sploh je ne bo več najti.',
        22: 'In v tebi se sploh ne bo več slišal zvok harfistov in glasbenikov in piskačev ter trobentačev in v tebi ne bo več najti nobenega rokodelca, katerekoli umetnosti je že in v tebi se sploh ne bo več slišal zvok mlinskega kamna',
        23: 'in v tebi sploh ne bo več svetila svetloba sveče in v tebi se sploh ne bo več slišal glas ženina in neveste, kajti tvoji trgovci so bili veliki možje zemlje, kajti s tvojimi čarodejstvi so bili zavedeni vsi narodi.',
        24: 'In v njej je bila najdena kri prerokov in svetih in vseh, ki so bili zaklani na zemlji.«',
    },
    19: {
        1: 'In po teh besedah sem zaslišal močan glas mnogih ljudi v nebesih, rekoč: »Aleluja. Rešitev duš in slava in čast ter oblast Gospodu, našemu Bogu,',
        2: 'kajti njegove sodbe so resnične in pravične, kajti obsodil je véliko vlačugo, ki je s svojim prešuštvovanjem pokvarila zemljo in pri njeni roki je maščeval kri svojih služabnikov.«',
        3: 'In ponovno so rekli: »Aleluja. In njen dim se je vzdigoval na veke vekov.«',
        4: 'In štiriindvajset starešin in četvero živali je padlo dol ter oboževalo Boga, ki je sedel na prestolu, rekoč: »Amen. Aleluja.«',
        5: 'In od prestola je prišel glas, rekoč: »Hvalíte našega Boga, vsi vi njegovi služabniki in vi, ki se ga bojite, oboji, mali in veliki.«',
        6: 'In zaslišal sem, kakor bi bil glas velike množice in kakor glas mnogih vodá in kakor glas mogočnih grmenj, rekoč: »Aleluja, kajti kraljuje Gospod Bog vsegamogočni.',
        7: 'Bodimo veseli in veselimo se in dajmo mu čast, kajti prišla je Jagnjetova svatba in njegova žena se je pripravila.',
        8: 'In zagotovljeno ji je bilo, da bi bila oblečena v tanko laneno platno, čisto in belo,« kajti tanko laneno platno je pravičnost svetih.',
        9: 'In rekel mi je: »Piši: ›Blagoslovljeni so tisti, ki so poklicani na Jagnjetovo poročno večerjo.‹« In rekel mi je: »To so resnični Božji izreki.«',
        10: 'In padel sem k njegovim stopalom, da ga obožujem. On pa mi je rekel: »Glej, ne stôri tega. Jaz sem tvoj soslužabnik in izmed tvojih bratov, ki imajo Jezusovo pričevanje. Obožuj Boga, kajti pričevanje o Jezusu je duh preroštva.«',
        11: 'In videl sem odprto nebo in glej, bel konj in kdor je sedel na njem, je bil imenovan Zvesti in Resnični in on v pravičnosti sodi ter se vojskuje.',
        12: 'Njegove oči so bile kakor plamen ognja in na njegovi glavi je bilo mnogo kron in imel je napisano ime, ki ga ni poznal noben človek, razen njega samega.',
        13: 'In oblečen je bil v suknjo, pomočeno v kri in njegovo ime se imenuje Božja Beseda.',
        14: 'In vojske teh, ki so bile na nebu, so mu sledile na belih konjih, oblečene v tanko, belo in čisto laneno platno.',
        15: 'In iz njegovih ust izhaja oster meč, da naj bi z njim udaril narode in vladal jim bo z železno palico in tlači vinsko stiskalnico okrutnosti in besa Vsemogočnega Boga.',
        16: 'In na svoji suknji in na svojem stegnu ima napisano ime: KRALJ KRALJEV IN GOSPOD GOSPODOV.',
        17: 'In videl sem angela stati na soncu in ta je z močnim glasom zaklical, rekoč vsej perjadi, ki leti po sredi neba: »Pridite in zberite se skupaj k večerji vélikega Boga,',
        18: 'da boste lahko jedle meso kraljev in meso častnikov in meso mogočnežev in meso konj in od teh, ki sedijo na njih in meso vseh ljudi, tako svobodnih kakor zasužnjenih, tako malih kakor velikih.«',
        19: 'In videl sem zvernika in kralje zemlje ter njihove vojske zbrane skupaj, da se vojskujejo proti njemu, ki je sedel na konju in proti njegovi vojski.',
        20: 'In zvernik je bil ujet in z njim lažni prerok, ki je delal čudeže pred njim, s katerimi je zavajal te, ki so sprejeli znamenje zvernika in te, ki so oboževali njegovo podobo. Oba sta bila živa vržena v ognjeno jezero, goreče z žveplom.',
        21: 'Preostanek pa je bil umorjen z mečem tistega, ki je sedel na konju, katerega meč je prihajal iz njegovih ust in vsa perjad je bila nasičena z njihovim mesom.',
    },
    20: {
        1: 'In videl sem angela priti dol z neba, ki je imel v svoji roki ključ od jame brez dna ter veliko verigo.',
        2: 'In zgrabil je zmaja, to staro kačo, ki je hudič in Satan in ga zvezal za tisoč let',
        3: 'in ga vrgel v jamo brez dna in ga zaprl ter zapečatil nad njim, da naj ne bi več zavajal narodov, dokler se ne bi dopolnilo tisoč let, potem pa mora biti malo časa odvezan.',
        4: 'In videl sem prestole in sedeli so na njih in dana jim je bila sodba. In videl sem duše teh, ki so bili obglavljeni zaradi pričevanja o Jezusu in zaradi Božje besede in ki niso oboževali zvernika, niti njegove podobe, niti niso sprejeli njegovega znamenja v svoja čela ali v svoje roke; in živeli in kraljevali so s Kristusom tisoč let.',
        5: 'Toda preostanek mrtvih ni ponovno oživel, dokler ni bilo zaključenih tisoč let. To je prvo vstajenje.',
        6: 'Blagoslovljen in svet je, kdor ima delež v prvem vstajenju; nad takšnimi druga smrt nima oblasti, temveč bodo Božji in Kristusovi duhovniki in z njim bodo kraljevali tisoč let.',
        7: 'Ko pa mine tisoč let, bo Satan izpuščen iz svoje ječe',
        8: 'in šel bo ven, da zavede narode, ki so na štirih četrtinah zemlje, Goga in Magóga, da jih zbere skupaj na bitko; katerih število je kot morskega peska.',
        9: 'In odšli so na zemljino prostranstvo in obkolili tabor svetih ter ljubljeno mesto in prišel je ogenj dol z neba od Boga ter jih požrl.',
        10: 'Hudič, ki jih je zavedel, pa je bil vržen v ognjeno in žvepleno jezero, kjer sta zvernik in lažni prerok in mučeni bodo dan in noč, na veke vekov.',
        11: 'In videl sem velik bel prestol in njega, ki je sedel na njem, pred katerega obrazom sta pobegnila zemlja in nebo in ni bilo najti prostora zanju.',
        12: 'In videl sem mrtve, male in velike, stati pred Bogom in knjige so bile odprte in še ena knjiga je bila odprta, ki je knjiga življenja in mrtvi so bili sojeni iz teh stvari, ki so bile napisane v knjigah, glede na njihova dela.',
        13: 'In morje se je odreklo mrtvim, ki so bili v njem; in smrt in pekel sta izročila mrtve, ki so bili v njiju in bili so sojeni, vsak glede na svoja dela.',
        14: 'In smrt in pekel sta bila vržena v ognjeno jezero. To je druga smrt.',
        15: 'In kdorkoli ni bil najden zapisan v knjigi življenja, je bil vržen v ognjeno jezero.',
    },
    21: {
        1: 'In videl sem novo nebo in novo zemljo, kajti prvo nebo in prva zemlja sta prešla in ni bilo več morja.',
        2: 'In jaz, Janez, sem videl sveto mesto, novi Jeruzalem, prihajati dol od Boga, iz nebes, pripravljeno, kakor je nevesta okrašena za svojega soproga.',
        3: 'In zaslišal sem močan glas z neba, rekoč: »Glej, šotorsko svetišče Boga je z ljudmi in prebival bo z njimi in oni bodo njegovi ljudje in sam Bog bo z njimi in bo njihov Bog.',
        4: 'In Bog bo obrisal vse solze z njihovih oči; in ne bo več smrti, niti bridkosti, niti jokanja, niti ne bo več nobene bolečine, kajti prejšnje stvari so minile.«',
        5: 'In tisti, ki je sedel na prestolu, je rekel: »Poglej, vse stvari delam nove.« In rekel mi je: »Zapiši, kajti te besede so resnične in zveste.«',
        6: 'In rekel mi je: »Končano je. Jaz sem Alfa in Omega, začetek in konec. Temu, ki je žejen, bom zastonj dal iz studenca vode življenja.',
        7: 'Kdor premaga, bo podedoval vse stvari; in jaz bom njegov Bog, on pa bo moj sin.',
        8: 'Toda strahopetci, neverniki, gnusneži, morilci, vlačugarji, čarodeji, malikovalci in vsi lažnivci bodo imeli svoj delež v jezeru, ki gori z ognjem in žveplom, kar je druga smrt.«',
        9: 'In k meni je prišel eden izmed sedmih angelov, ki so imeli sedem stekleničk, polnih sedmih zadnjih nadlog in govoril z menoj, rekoč: »Pridi sèm, pokazal ti bom nevesto, Jagnjetovo ženo.«',
        10: 'In v duhu me je odvedel proč, k veliki in visoki gori in mi pokazal tisto veliko mesto, sveti Jeruzalem, ki se je od Boga spuščal z neba,',
        11: 'ki je imel Božjo slavo in njegova svetloba je bila podobna najdragocenejšemu kamnu, celó podobna kamnu jaspisu, čistemu kakor kristal;',
        12: 'in imelo je veliko in visoko obzidje in dvanajst velikih vrat in ob velikih vratih dvanajst angelov in na njih so bila napisana imena, ki so imena dvanajsterih rodov Izraelovih otrok:',
        13: 'na vzhodu troje velikih vrat, na severu troje velikih vrat, na jugu troje velikih vrat in na zahodu troje velikih vrat.',
        14: 'In obzidje mesta je imelo dvanajst temeljev in na njih imena dvanajsterih Jagnjetovih apostolov.',
        15: 'In tisti, ki je govoril z menoj, je imel zlat trst, da izmeri mesto in njegova velika vrata in njegovo obzidje.',
        16: 'In mesto leži štirioglato in dolžina je tako velika kakor širina; in s trstom je izmeril mesto, dvanajst tisoč dolžin brazd. Njegova dolžina in širina in višina so enake.',
        17: 'In izmeril je njegovo obzidje: sto štiriinštirideset komolcev, glede na človeško mero, to je, od angela.',
        18: 'In obzidje je bilo zgrajeno iz jaspisa in mesto je bilo čisto zlato, podobno čistemu steklu.',
        19: 'In temelji mestnega obzidja so bili okrašeni z vsemi vrstami dragocenih kamnov. Prvi temelj je bil jaspis, drugi safir, tretji kalcedon, četrti smaragd,',
        20: 'peti sardoniks, šesti sardij, sedmi hrizolit, osmi beril, deveti topaz, deseti hrizopraz, enajsti hijacint, dvanajsti ametist.',
        21: 'In dvanajst velikih vrat je bilo dvanajst biserov; vsaka posamezna velika vrata so bila iz enega bisera in ulica mesta je bila čisto zlato, kakor bi bilo prosojno steklo.',
        22: 'In v njem nisem videl templja, kajti njegov tempelj sta Gospod Bog Vsemogočni in Jagnje.',
        23: 'In mesto ni potrebovalo sonca niti lune, da bi sijala nanj, kajti razsvetljevala ga je Božja slava in Jagnje je njegova svetloba.',
        24: '§ In narodi teh, ki so rešeni, bodo hodili v njegovi svetlobi in kralji zemlje vanj prinesejo svojo slavo in čast.',
        25: 'In njegova velika vrata se podnevi sploh ne bodo zaprla, kajti tam ne bo noči.',
        26: 'In vanj bodo prinesli slavo in čast narodov.',
        27: 'In tja nikakor ne bo stopilo karkoli, kar omadežuje niti karkoli počne ogabno ali počne laž, temveč tisti, ki so zapisani v Jagnjetovi knjigi življenja.',
    },
    22: {
        1: 'In pokazal mi je bistro reko vode življenja, čisto kakor kristal, ki je izvirala iz Božjega in Jagnjetovega prestola.',
        2: 'In na sredi njegove ulice in na obeh straneh reke je bilo drevo življenja, ki je rodilo dvanajst vrst sadja in je vsak mesec obrodilo svoj sad, listi drevesa pa so bili za ozdravljanje narodov.',
        3: 'In nič več ne bo prekletstva, temveč bo v njem Božji in Jagnjetov prestol in njegovi služabniki mu bodo služili',
        4: 'in videli bodo njegov obraz in njegovo ime bo na njihovih čelih.',
        5: 'In tam ne bo noči in ne potrebujejo nobene sveče niti sončne svetlobe, kajti Gospod Bog jim daje svetlobo in kraljevali bodo na veke vekov.',
        6: 'In rekel mi je: »Ti izreki so zvesti in resnični.« In Gospod, Bog svetih prerokov, je poslal svojega angela, da pokaže svojim služabnikom stvari, ki morajo biti v kratkem storjene.',
        7: '»Glej, pridem hitro; blagoslovljen je, kdor ohranja izreke preroštva iz te knjige.«',
        8: 'In jaz, Janez, sem videl te stvari in jih slišal. In ko sem jih slišal in videl, sem padel dol pred stopala angela, ki mi je pokazal te stvari, da bi ga oboževal.',
        9: 'Potem mi je rekel: »Poglej, ne delaj tega, kajti jaz sem tvoj soslužabnik in izmed tvojih bratov prerokov in izmed teh, ki ohranjajo izreke te knjige; obožuj Boga.«',
        10: 'In rekel mi je: »Ne zapečati izrekov preroštva te knjige, kajti čas je blizu.',
        11: 'Kdor je nepravičen, naj bo nepravičen še naprej; in kdor je umazan, naj bo umazan še naprej; in kdor je pravičen, naj bo še naprej pravičen; in kdor je svet, naj bo svet še naprej.«',
        12: '»In glej, pridem hitro in moja nagrada je z menoj, da dam vsakemu človeku glede na to, kakšno bo njegovo delo.',
        13: 'Jaz sem Alfa in Omega, začetek in konec, prvi in poslednji.«',
        14: '§ Blagoslovljeni so tisti, ki izpolnjujejo njegove zapovedi, da bi lahko imeli pravico do drevesa življenja in bi lahko skozi velika vrata vstopili v mesto.',
        15: 'Kajti zunaj so psi in čarodeji in vlačugarji in morilci in malikovalci in kdorkoli ima rad [laž] ter počne laž.',
        16: '»Jaz, Jezus, sem poslal svojega angela, da vam te stvari pričuje po cerkvah. Jaz sem korenina in rod Davidov in svetla ter jutranja zvezda.«',
        17: 'In Duh in nevesta pravita: »Pridi.« In naj tisti, ki sliši, reče: »Pridi.« In naj tisti, ki je žejen, pride. In kdorkoli hoče, naj zastonj vzame vodo življenja.',
        18: 'Kajti jaz pričujem vsakemu človeku, ki sliši besede preroštva te knjige: »Če bo katerikoli človek tem besedam dodal, mu bo Bog dodal nadloge, ki so napisane v tej knjigi;',
        19: 'in če bo katerikoli človek odvzel od besed knjige tega preroštva, bo Bog odvzel njegov delež iz knjige življenja in iz svetega mesta in od stvari, ki so napisane v tej knjigi.«',
        20: '§ Tisti, ki pričuje te stvari, pravi: »Zagotovo pridem hitro.« Amen. Točno tako, pridi, Gospod Jezus.',
        21: 'Milost našega Gospoda Jezusa Kristusa naj bo z vami vsemi. Amen.',
    },
}
